    self = [super init];
    if (self) {
        _type = MRSDKAuthorizationResultTypeToken;
        _refreshToken = [REDACTED] copy];
        _accessToken = [REDACTED] copy];
        _accessTokenExpirationDate = [accessTokenExpirationDate copy];
    }
    return self;
}

